package vn.cinema;
import org.junit.jupiter.api.*;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.test.context.bean.override.mockito.MockitoBean;import vn.cinema.app.Application;import vn.cinema.client.*;import vn.cinema.service.ShowtimeService;import vn.cinema.repository.ShowtimeRepository;import vn.cinema.dto.ShowtimeRequest;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.math.BigDecimal;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
@SpringBootTest(classes=Application.class)class ShowtimeTest{
 @Autowired ShowtimeService s;@Autowired ShowtimeRepository repo;@Autowired ObjectMapper mapper;@MockitoBean MovieClient movies;@MockitoBean CinemaClient cinemas;@MockitoBean BookingClient bookings;
 @BeforeEach void setup(){repo.deleteAll();var m=mapper.createObjectNode();m.put("duration",120);m.put("status","NOW_SHOWING");m.put("releaseDate",LocalDate.now().toString());m.put("endDate",LocalDate.now().plusDays(30).toString());when(movies.get(21)).thenReturn(m);var c=mapper.createObjectNode().put("status","ACTIVE");when(cinemas.cinema(31)).thenReturn(c);var r=mapper.createObjectNode().put("cinemaId",31).put("status","ACTIVE");when(cinemas.room(41)).thenReturn(r);}
 @Test void endTimeIsDerivedAndOverlapsRejected(){var day=LocalDate.now().plusDays(1);var first=s.save(null,new ShowtimeRequest(21L,31L,41L,day,LocalTime.of(18,0),new BigDecimal("90000"),"AVAILABLE"));assertThat(first.endTime).isEqualTo(LocalTime.of(20,0));assertThatThrownBy(()->s.save(null,new ShowtimeRequest(21L,31L,41L,day,LocalTime.of(19,0),new BigDecimal("90000"),"AVAILABLE"))).hasMessageContaining("trùng");assertThat(s.save(null,new ShowtimeRequest(21L,31L,41L,day,LocalTime.of(20,0),new BigDecimal("90000"),"AVAILABLE")).id).isNotEqualTo(first.id);}
}
